// Part: room: Entrance hall (parts/room-2.mjs). Grand civic hall, inner air x11..29, z15..25, y4..9. A red runner down the
// centre line from the vestibule archway to the rear door; two notice boards flank the archway; a pair of fence-and-slab
// tables with benches on each side (the waiting groups); barrels and flower pots in the back corners; hanging lanterns
// from the upper floor over the runner and each table. The stair flights (x11..12, x28..29) and the arcade gaps are
// the shell's and the bays', so the rows keep z14/15 clear at x12..16 and x24..28 and the first cell of each doorway.
import { layers, B } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";

// Origin [11, 4, 15]: rows run along +x (x11..29), successive rows along +z (z15..25).
const ORIGIN = [11, 4, 15];

const LEGEND = {
  R: "red_carpet",
  N: ["dark_oak_stairs", { facing: "north" }], // bench, back to the north, seat faces south
  S: ["dark_oak_stairs", { facing: "south" }], // bench, back to the south, seat faces north
  T: "dark_oak_fence", // table leg
  B: "barrel",
  P: "flower_pot",
};

const TOP_LEGEND = { L: ["dark_oak_slab", { type: "bottom" }] }; // table top, at y5
const LAMP_LEGEND = { G: ["lantern", { hanging: "true" }] }; // hanging lantern, under the upper floor at y10

// Floor layer, y4. Rows are z15..z25; the arcade and doorway cells stay bare.
const FLOOR = [
  ".........R.........", // z15
  ".........R.........", // z16
  "....N....R....N....", // z17
  "....T....R....T....", // z18
  "....S....R....S....", // z19
  ".........R.........", // z20
  "....N....R....N....", // z21
  "....T....R....T....", // z22
  "....S....R....S....", // z23
  "..B......R......B..", // z24
  ".........R.........", // z25
];

// Table tops, y5: a slab on each fence.
const TOP = [
  ".........",
];

export function build(g) {
  layers(g, ORIGIN, LEGEND, [FLOOR]);
}

